Action.Str:
var s = (local("evtprm2") || "") + " | " + (local("evtprm3") || "");
var tipo = "", valor = "", estab = "", parcelas = "1", cartao = "nubank", m;

if (m = s.match(/Compra de R\$\s?([\d.]+,\d{2}) APROVADA em (.+?) para o cartão com final (\d{4})/)) {
  tipo = "despesa_credito"; valor = m[1]; estab = m[2];
} else if (/débito/i.test(s) && (m = s.match(/Compra de R\$\s?([\d.]+,\d{2}) em (.+?)\.?\s*$/))) {
  // Débito Nubank: "Compra no débito aprovada | Compra de R$ 5,90 em EMV CMT*156596385"
  tipo = "despesa_debito"; valor = m[1]; estab = m[2];
} else if (m = s.match(/Você pagou R\$\s?([\d.]+,\d{2}) a (.+?)\.?\s*\|.*fatura do seu Cartão Mercado Pago/i)) {
  // Crédito Mercado Pago (perfil do app Mercado Pago). Sem a frase da fatura (saldo, Pix) não é do cartão.
  tipo = "despesa_credito"; valor = m[1]; estab = m[2]; cartao = "mp";
} else if ((/transfer[eê]ncia (realizada|enviada)|pix enviado/i.test(s) ||
            /boleto/i.test(s) && /\b(pago|paga|realizad[oa]|confirmad[oa]|efetuad[oa])\b/i.test(s) && !/venc|agendad|lembrete/i.test(s)) &&
           (m = s.match(/R\$\s?([\d.]+,\d{2})/))) {
  // Pix enviado ou boleto pago: paga uma conta prevista (textos ainda sem print, a conferir).
  // Lembrete ("vence"), agendamento e boleto sem "pago/realizado" ficam de fora.
  tipo = "conta_saida"; valor = m[1];
  var q = s.match(/\bpara\s+(?!o cartão)(.+?)\s*(?:\s(?:foi|com sucesso|via)\b|\.(?:\s|$)|\||$)/i);
  estab = q ? q[1] : "";
} else if (/transfer[eê]ncia recebida|pix recebido|voc[eê] recebeu/i.test(s) && (m = s.match(/R\$\s?([\d.]+,\d{2})/))) {
  // Pix recebido: recebe uma entrada prevista (texto ainda sem print, a conferir).
  tipo = "conta_entrada"; valor = m[1];
  var q = s.match(/R\$\s?[\d.]+,\d{2}\s+de\s+(.+?)\s*(?:\s(?:foi|com sucesso|via)\b|\.(?:\s|$)|\||$)/i) ||
          s.match(/\bde\s+(?!R\$)([^|]+?)\s*(?:\s(?:foi|com sucesso|via)\b|\.(?:\s|$)|\||$)/i);
  estab = q ? q[1] : "";
} else if (m = s.match(/R\$\s?([\d.]+,\d{2}) em (\d+)x no crédito.*?APROVADO em (.+?)\.?$/)) {
  tipo = "despesa_nupay"; valor = m[1]; parcelas = m[2]; estab = m[3];
} else if (m = s.match(/cobrança paga de R\$\s?([\d.]+,\d{2})/)) {
  tipo = "receita_nupay"; valor = m[1];
}

valor = valor.replace(/\./g, "").replace(",", ".");

setLocal("tipo", tipo || "nenhum");
setLocal("valor", valor);
setLocal("estab", estab);
setLocal("parcelas", parcelas);
setLocal("cartao", cartao);

// Lança sozinho se o estabelecimento tem atalho (fin_atalho): a Edge Function responde lancado.
var agora = Math.floor(Date.now() / 1000);
setLocal("agora", String(agora));
setLocal("body", JSON.stringify({ tipo: local("tipo"), valor: local("valor"), estab: local("estab"),
  parcelas: local("parcelas"), cartao: local("cartao"), ts: String(agora), auto: true }));

// Sem resposta, erro ou sem atalho: segue o fluxo de sempre (notificação pra tocar).
var r = {};
try { r = JSON.parse(local("http_data") || "{}"); } catch (e) {}
var ok = String(local("http_response_code") || "").charAt(0) === "2" && (r.lancado === true || r.pago === true);
setLocal("lancado", ok ? "sim" : "nao");
if (ok) setLocal("aviso", r.texto ? r.texto : r.nome + " R$ " + local("valor").replace(".", ",") + " · " + String(r.categ || "") + (r.forma ? " · " + r.forma : ""));
setLocal("avisotit", r.pago ? (local("tipo") === "conta_entrada" ? "Recebido sozinho" : "Pago sozinho") : "Lançado sozinho");

var agora = parseInt(local("agora"), 10) || Math.floor(Date.now() / 1000);
var d = new Date();
var p2 = function (n) { return ("0" + n).slice(-2); };
var hora = p2(d.getHours()) + ":" + p2(d.getMinutes()) + ":" + p2(d.getSeconds());
var quem = local("estab") || (local("tipo") === "conta_entrada" ? "Recebido" : local("tipo") === "conta_saida" ? "Pagamento" : "");
var base = quem + " - R$ " + local("valor").replace(".", ",") + " (" + hora + ")";

var raw = global("FINPEND"), pend = {};
try { if (raw && raw.charAt(0) !== "%") pend = JSON.parse(raw); } catch (e) {}
for (var k in pend) { if (agora - pend[k].ts > 7 * 86400) delete pend[k]; }

var titulo = base, n = 2;
while (pend[titulo]) { titulo = base + " #" + n++; }

pend[titulo] = { tipo: local("tipo"), valor: local("valor"), estab: local("estab"),
                 parcelas: local("parcelas"), cartao: local("cartao"), ts: agora };
setGlobal("FINPEND", JSON.stringify(pend));
setLocal("titulo", titulo);
